import * as React from "react"
import { cva, type VariantProps } from "class-variance-authority"

import { Slot } from "@/lib/slot"
import { cn } from "@/lib/utils"

/**
 * Trigger an action or commit a workflow step; exactly one primary action per surface.
 *
 * Variant grammar:
 * - `default` — the mode-resolved action fill for ordinary primary actions.
 * - `brand` / `brand-primary` — the fixed Nextlink cobalt fill on the ordinary
 *   button shadow, for identity-carrying actions (hero, auth, launch).
 * - `brand-secondary` — the promoted gold fill on ink, on the same ordinary button
 *   shadow. It is *the* one promoted control: at most one per screen, a priority
 *   cue, never a status colour and never on a form control.
 * - `destructive` / `outline` / `secondary` / `ghost` / `link` — standard tiers.
 *
 * Sizing: `default` and `icon` derive their height from `--density-control-height`
 * (36px compact · 40px standard · 44px spacious · 44px under `(pointer: coarse)`);
 * `xs` / `sm` / `lg` stay fixed at 24 / 32 / 40px.
 *
 * Disabled buttons keep pointer events (only the cursor changes) so a wrapping
 * `Tooltip` or `aria-describedby` can explain a recoverable cause.
 */
const buttonVariants = cva(
  "relative inline-flex shrink-0 cursor-pointer items-center justify-center gap-2 rounded-md border border-transparent bg-transparent text-sm leading-5 font-medium whitespace-nowrap no-underline transition-[background-color,color,box-shadow,border-color,opacity] duration-150 outline-none focus-visible:border-ring focus-visible:outline-none focus-visible:shadow-[var(--ring-focus)] disabled:cursor-not-allowed disabled:opacity-50 aria-disabled:cursor-not-allowed aria-disabled:not-data-loading:opacity-50 data-loading:cursor-progress aria-invalid:border-destructive [&_svg]:pointer-events-none [&_svg]:shrink-0 [&_svg:not([class*='size-'])]:size-4",
  {
    variants: {
      variant: {
        default:
          "bg-primary text-primary-foreground shadow-button hover:bg-primary/90",
        destructive:
          "bg-destructive text-white hover:bg-destructive/90 dark:bg-destructive/60",
        outline:
          "border-border bg-background shadow-xs hover:bg-accent hover:text-accent-foreground dark:bg-card dark:hover:bg-accent",
        secondary:
          "border-border bg-secondary text-secondary-foreground shadow-xs hover:bg-accent",
        ghost: "hover:bg-accent hover:text-accent-foreground",
        link: "text-link underline-offset-4 hover:underline",
        // Brand fills use the same `shadow-button` drop as `default`: depth is one
        // soft shadow, never a brand-coloured glow.
        brand: "bg-brand-blue text-white shadow-button hover:bg-brand-blue/90",
        "brand-primary":
          "bg-brand-blue text-white shadow-button hover:bg-brand-blue/90",
        "brand-secondary":
          "bg-priority-gold text-tertiary-foreground shadow-button hover:bg-priority-gold/90",
      },
      size: {
        default:
          "h-[var(--density-control-height,2.25rem)] px-4 py-2 has-[>svg:first-child]:pl-3 has-[>svg:last-child]:pr-3",
        xs: "h-6 gap-1 px-2 [&_svg:not([class*='size-'])]:size-3",
        sm: "h-8 gap-1.5 px-3 has-[>svg:first-child]:pl-2.5 has-[>svg:last-child]:pr-2.5",
        lg: "h-10 px-6 has-[>svg:first-child]:pl-4 has-[>svg:last-child]:pr-4",
        icon: "size-[var(--density-control-height,2.25rem)] p-0",
        "icon-xs": "size-6 p-0 [&_svg:not([class*='size-'])]:size-3",
        "icon-sm": "size-8 p-0",
        "icon-lg": "size-10 p-0",
      },
    },
    defaultVariants: {
      variant: "default",
      size: "default",
    },
  }
)

export interface ButtonProps
  extends React.ComponentProps<"button">,
    VariantProps<typeof buttonVariants> {
  asChild?: boolean
  /**
   * In-button indeterminate affordance for the action itself: the label stays
   * put and keeps full contrast, a spinner is prefixed, and the button sets
   * `aria-busy="true"` and `aria-disabled="true"` with a click guard. It never
   * sets native `disabled`, so focus stays on the button while the action runs
   * and returns nowhere else when it resolves. This is the one sanctioned
   * indeterminate spinner (design-policy-v3 §6B) — region-, page- or
   * data-surface loading uses skeletons or determinate progress. Use it on the
   * button that submitted, nothing wider.
   *
   * With `asChild` the spinner is prepended inside the rendered child rather than
   * beside it, because `Slot` clones a single element.
   */
  loading?: boolean
}

/**
 * `Slot.Root` clones one element child, so the spinner cannot be a sibling of
 * `children` under `asChild` — that would hand `Slot` an array and it renders
 * nothing at all. Prepend the spinner into the child's own children instead.
 */
function withSpinner(children: React.ReactNode, spinner: React.ReactNode) {
  if (
    spinner == null ||
    !React.isValidElement<{ children?: React.ReactNode }>(children)
  ) {
    return children
  }

  return React.cloneElement(
    children,
    undefined,
    spinner,
    ...React.Children.toArray(children.props.children)
  )
}

function Button({
  className,
  variant = "default",
  size = "default",
  asChild = false,
  loading = false,
  disabled,
  children,
  onClick,
  onKeyDown,
  ...props
}: ButtonProps) {
  const Comp = asChild ? Slot.Root : "button"
  const blocked = Boolean(disabled) || loading
  const spinner = loading ? (
    <span
      key="button-spinner"
      data-slot="button-spinner"
      aria-hidden="true"
      className="size-3.5 shrink-0 animate-[spin_0.8s_linear_infinite] rounded-full border-2 border-current border-r-transparent"
    />
  ) : null

  // Activation guard: while loading (or disabled on an `asChild` host that has
  // no native `disabled`) the button stays focusable but cannot fire. The
  // `preventDefault` also cancels the synthetic click a form dispatches at its
  // default submit button on Enter-in-input, so implicit submission is covered.
  const handleClick = (event: React.MouseEvent<HTMLButtonElement>) => {
    if (blocked) {
      event.preventDefault()
      event.stopPropagation()
      return
    }
    onClick?.(event)
  }

  // `asChild` hosts (links, spans) activate on Enter/Space through their own
  // key handling; block only those two keys so Tab and arrows still pass.
  const handleKeyDown = (event: React.KeyboardEvent<HTMLButtonElement>) => {
    if (asChild && blocked && (event.key === "Enter" || event.key === " ")) {
      event.preventDefault()
      event.stopPropagation()
      return
    }
    onKeyDown?.(event)
  }

  return (
    <Comp
      data-slot="button"
      data-variant={variant}
      data-size={size}
      data-loading={loading || undefined}
      aria-busy={loading || undefined}
      aria-disabled={loading || (asChild && Boolean(disabled)) || undefined}
      // Native `disabled` only for an explicit `disabled` on a real <button>;
      // `loading` never uses it (focus would drop to <body>), and the arbitrary
      // element `asChild` renders may not accept it at all.
      disabled={!asChild && disabled ? true : undefined}
      className={cn(buttonVariants({ variant, size, className }))}
      onClick={handleClick}
      onKeyDown={handleKeyDown}
      {...props}
    >
      {asChild ? (
        withSpinner(children, spinner)
      ) : (
        <>
          {spinner}
          {children}
        </>
      )}
    </Comp>
  )
}

export { Button, buttonVariants }

import * as React from "react"

import { cn } from "@/lib/utils"

type SlotRootProps = React.HTMLAttributes<HTMLElement> & {
  children?: React.ReactNode
  [key: string]: unknown
}

function mergeRefs<T>(
  ...refs: Array<React.Ref<T> | undefined>
): React.RefCallback<T> {
  return (value) => {
    for (const ref of refs) {
      if (!ref) continue
      if (typeof ref === "function") {
        ref(value)
        continue
      }
      ;(ref as React.MutableRefObject<T | null>).current = value
    }
  }
}

function composeEventHandlers<E>(
  childHandler: ((event: E) => void) | undefined,
  slotHandler: ((event: E) => void) | undefined
) {
  return (event: E) => {
    childHandler?.(event)
    slotHandler?.(event)
  }
}

function mergeProps(
  childProps: Record<string, unknown>,
  slotProps: Record<string, unknown>
) {
  const merged: Record<string, unknown> = {
    ...slotProps,
    ...childProps,
  }

  if (slotProps.className || childProps.className) {
    merged.className = cn(
      typeof slotProps.className === "string" ? slotProps.className : undefined,
      typeof childProps.className === "string"
        ? childProps.className
        : undefined
    )
  }

  if (slotProps.style || childProps.style) {
    merged.style = {
      ...(slotProps.style as React.CSSProperties | undefined),
      ...(childProps.style as React.CSSProperties | undefined),
    }
  }

  for (const key of Object.keys(slotProps)) {
    if (!key.startsWith("on")) continue
    const slotHandler = slotProps[key]
    const childHandler = childProps[key]
    if (typeof slotHandler === "function" || typeof childHandler === "function") {
      merged[key] = composeEventHandlers(
        childHandler as ((event: unknown) => void) | undefined,
        slotHandler as ((event: unknown) => void) | undefined
      )
    }
  }

  return merged
}

const SlotRoot = React.forwardRef<HTMLElement, SlotRootProps>(
  ({ children, ...props }, forwardedRef) => {
    if (!React.isValidElement(children)) {
      return null
    }

    const child = children as React.ReactElement<{
      ref?: React.Ref<HTMLElement>
    }>

    return React.cloneElement(child, {
      ...mergeProps(
        child.props as Record<string, unknown>,
        props as Record<string, unknown>
      ),
      ref: mergeRefs(child.props.ref, forwardedRef),
    })
  }
)

SlotRoot.displayName = "Slot.Root"

export const Slot = {
  Root: SlotRoot,
}

export type Theme = "light" | "dark" | "system";
export type ResolvedTheme = "light" | "dark";

export const STORAGE_KEY = "nextlink-theme";
export const MEDIA_QUERY = "(prefers-color-scheme: dark)";
export const THEME_ATTRIBUTE = "data-theme";
export const RESOLVED_THEME_ATTRIBUTE = "data-resolved-theme";
export const DEFAULT_THEME: Theme = "dark";
export const FALLBACK_RESOLVED_THEME: ResolvedTheme = "dark";
export const LIGHT_THEME_BACKGROUND = "#FFFFFF";
export const DARK_THEME_BACKGROUND = "#08111F";

export function isTheme(value: string | null | undefined): value is Theme {
  return value === "light" || value === "dark" || value === "system";
}

export function isResolvedTheme(
  value: string | null | undefined
): value is ResolvedTheme {
  return value === "light" || value === "dark";
}

export function resolveTheme(
  theme: Theme,
  systemTheme: ResolvedTheme
): ResolvedTheme {
  return theme === "system" ? systemTheme : theme;
}

export function applyThemeToDom(theme: Theme, resolvedTheme: ResolvedTheme) {
  if (typeof document === "undefined") {
    return;
  }

  const root = document.documentElement;
  const isDark = resolvedTheme === "dark";

  root.classList.toggle("dark", isDark);
  root.style.colorScheme = resolvedTheme;
  root.style.backgroundColor = isDark
    ? DARK_THEME_BACKGROUND
    : LIGHT_THEME_BACKGROUND;
  root.setAttribute(THEME_ATTRIBUTE, theme);
  root.setAttribute(RESOLVED_THEME_ATTRIBUTE, resolvedTheme);
}

export function getThemeBootScript() {
  return `
(() => {
  const root = document.documentElement;
  const isTheme = (value) =>
    value === "light" || value === "dark" || value === "system";

  try {
    const storedTheme = window.localStorage.getItem(${JSON.stringify(STORAGE_KEY)});
    const theme = isTheme(storedTheme)
      ? storedTheme
      : ${JSON.stringify(DEFAULT_THEME)};
    const systemTheme = window.matchMedia(${JSON.stringify(MEDIA_QUERY)}).matches
      ? "dark"
      : "light";
    const resolvedTheme = theme === "system" ? systemTheme : theme;
    const isDark = resolvedTheme === "dark";

    root.classList.toggle("dark", isDark);
    root.style.colorScheme = resolvedTheme;
    root.style.backgroundColor = isDark
      ? ${JSON.stringify(DARK_THEME_BACKGROUND)}
      : ${JSON.stringify(LIGHT_THEME_BACKGROUND)};
    root.setAttribute(${JSON.stringify(THEME_ATTRIBUTE)}, theme);
    root.setAttribute(${JSON.stringify(RESOLVED_THEME_ATTRIBUTE)}, resolvedTheme);
  } catch {
    root.classList.add("dark");
    root.style.colorScheme = ${JSON.stringify(FALLBACK_RESOLVED_THEME)};
    root.style.backgroundColor = ${JSON.stringify(DARK_THEME_BACKGROUND)};
    root.setAttribute(${JSON.stringify(THEME_ATTRIBUTE)}, ${JSON.stringify(DEFAULT_THEME)});
    root.setAttribute(
      ${JSON.stringify(RESOLVED_THEME_ATTRIBUTE)},
      ${JSON.stringify(FALLBACK_RESOLVED_THEME)}
    );
  }
})();
`.trim();
}

"use client";

import {
  createContext,
  useCallback,
  useContext,
  useEffect,
  useMemo,
  useState,
  type ReactNode,
} from "react";

import {
  applyThemeToDom,
  DEFAULT_THEME,
  MEDIA_QUERY,
  STORAGE_KEY,
  THEME_ATTRIBUTE,
  isTheme,
  resolveTheme,
  type ResolvedTheme,
  type Theme,
} from "@/lib/theme-config";

type ThemeContextValue = {
  theme: Theme;
  resolvedTheme: ResolvedTheme | undefined;
  setTheme: (theme: Theme) => void;
};

const ThemeContext = createContext<ThemeContextValue | null>(null);

function getStoredTheme(): Theme | null {
  if (typeof window === "undefined") {
    return null;
  }

  const storedTheme = window.localStorage.getItem(STORAGE_KEY);

  return isTheme(storedTheme) ? storedTheme : null;
}

function getSystemTheme(): ResolvedTheme {
  if (typeof window === "undefined") {
    return "light";
  }

  return window.matchMedia(MEDIA_QUERY).matches ? "dark" : "light";
}

function getThemeFromDom(): Theme | null {
  if (typeof document === "undefined") {
    return null;
  }

  const theme = document.documentElement.getAttribute(THEME_ATTRIBUTE);

  return isTheme(theme) ? theme : null;
}

export function ThemeProvider({
  children,
}: Readonly<{
  children: ReactNode;
}>) {
  // Deterministic SSR-equivalent initial state. Do NOT read DOM/storage/matchMedia here.
  const [theme, setThemeState] = useState<Theme>(DEFAULT_THEME);
  const [resolvedTheme, setResolvedTheme] = useState<ResolvedTheme | undefined>(
    undefined
  );

  // First-mount sync: read the real stored theme + system, reconcile state with DOM.
  useEffect(() => {
    const storedTheme = getStoredTheme() ?? getThemeFromDom() ?? DEFAULT_THEME;
    const systemTheme = getSystemTheme();
    const nextResolvedTheme = resolveTheme(storedTheme, systemTheme);

    setThemeState(storedTheme);
    setResolvedTheme(nextResolvedTheme);
    applyThemeToDom(storedTheme, nextResolvedTheme);
  }, []);

  // Keep system-preference subscription alive; re-subscribe when theme changes.
  useEffect(() => {
    const mediaQuery = window.matchMedia(MEDIA_QUERY);

    const handleChange = () => {
      if (theme === "system") {
        const nextResolvedTheme = getSystemTheme();
        setResolvedTheme(nextResolvedTheme);
        applyThemeToDom(theme, nextResolvedTheme);
      }
    };

    mediaQuery.addEventListener("change", handleChange);

    return () => {
      mediaQuery.removeEventListener("change", handleChange);
    };
  }, [theme]);

  const setTheme = useCallback((nextTheme: Theme) => {
    const nextResolvedTheme = resolveTheme(nextTheme, getSystemTheme());

    setThemeState(nextTheme);
    setResolvedTheme(nextResolvedTheme);
    applyThemeToDom(nextTheme, nextResolvedTheme);
    window.localStorage.setItem(STORAGE_KEY, nextTheme);
  }, []);

  const value = useMemo<ThemeContextValue>(
    () => ({
      theme,
      resolvedTheme,
      setTheme,
    }),
    [resolvedTheme, setTheme, theme]
  );

  return <ThemeContext.Provider value={value}>{children}</ThemeContext.Provider>;
}

export function useTheme() {
  const context = useContext(ThemeContext);

  if (!context) {
    throw new Error("useTheme must be used within <ThemeProvider />");
  }

  return context;
}

import { clsx, type ClassValue } from "clsx";
import { twMerge } from "tailwind-merge";
import { format, formatDistanceStrict } from "date-fns";

export function cn(...inputs: ClassValue[]) {
  return twMerge(clsx(inputs));
}

/**
 * Invisible pointer-target extension for small controls (WCAG 2.5.8: every
 * pointer target is at least 24×24 CSS px as a hit area, not a glyph size).
 * Compose it into a control's className; the `after:` pseudo-element grows
 * the clickable box by 8px on each side horizontally and 6px vertically
 * without moving layout or enlarging the visible glyph. Tune per control by
 * overriding the `after:-inset-*` utilities through `cn`.
 */
export const hitArea =
  "relative after:absolute after:-inset-x-2 after:-inset-y-1.5 after:content-['']";

/**
 * Age of `date` measured from `now` in exact units — "12 seconds ago",
 * "3 minutes ago", "in 2 hours". Pass `now` for deterministic output (tests,
 * shared tickers such as `useNow`); it defaults to the current time.
 */
export function formatRelativeTime(
  date: string | Date | number,
  now: Date | number = Date.now()
): string {
  return formatDistanceStrict(new Date(date), now, { addSuffix: true });
}

export function formatDateTime(date: string | Date | null): string {
  if (!date) return "—";
  return format(new Date(date), "MMM d, yyyy h:mm a");
}

export function formatShortDate(date: string | Date | null): string {
  if (!date) return "—";
  return format(new Date(date), "MMM d, yyyy");
}
